/* Chart chrome is drawn only with Gravity UI theme tokens, so it follows
   light / dark / high-contrast themes without any extra code. */
.line-chart {
    position: relative;
    width: 100%;
    font-family: var(--g-font-family-sans);
}

.line-chart svg {
    display: block;
    overflow: visible;
    outline: none;
}

.line-chart svg:focus-visible {
    border-radius: var(--g-border-radius-s);
    box-shadow: 0 0 0 2px var(--g-color-line-focus);
}

.line-chart__grid line {
    stroke: var(--g-color-line-generic);
    stroke-width: 1;
    shape-rendering: crispEdges;
}

.line-chart__grid line.line-chart__baseline {
    stroke: var(--g-color-line-generic-accent);
}

